Q: How to use filter on link entity? A: <p>I just want to share this readable format of your expected query. Also like other answer mentioned, use Advanced find or fetchXML builder in XrmToolBox to build fetchxml query, you can view SQL and query expression equivalent there itself.</p>
<pre><code>QueryExpression query = new QueryExpression(&quot;product&quot;)
{
    ColumnSet = new ColumnSet(&quot;productname&quot;), 
    Criteria = new FilterExpression(LogicalOperator.And)
    {
        Conditions =
        {
               new ConditionExpression(&quot;productstatus&quot;, ConditionOperator.Equal, 0)
        }
    },
    LinkEntities =
    {
        new LinkEntity(&quot;product&quot;, &quot;phonecall&quot;, &quot;productid&quot;, &quot;regardingobjectid&quot;, JoinOperator.LeftOuter)
        {
            Columns = new ColumnSet(&quot;phonecallcategory&quot;),
            LinkCriteria = new FilterExpression(LogicalOperator.And)
            {
                Conditions =
                {
                    new ConditionExpression(&quot;statecode&quot;, ConditionOperator.NotEqual, 0),
                    new ConditionExpression(&quot;phonecallcategory&quot;, ConditionOperator.Equal, &quot;fun&quot;)
                }
            }
        }
    }
};
</code></pre>
